class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        position = 0

        for command in commands:
            if command == "RIGHT":
                position += 1
            elif command == "LEFT":
                position -= 1
            elif command == "DOWN":
                position += n
            elif command == "UP":
                position -= n

        return position

class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Count how many times each color is picked by each player
        player_color_count = {}

        for player, color in pick:
            if player not in player_color_count:
                player_color_count[player] = {}
            player_color_count[player][color] = player_color_count[player].get(color, 0) + 1

        # Count winning players
        winning_count = 0

        for player in range(n):
            # Player i wins if they have at least (i+1) balls of the same color
            if player in player_color_count:
                # Check if any of their picked colors has count >= (player + 1)
                for color, count in player_color_count[player].items():
                    if count >= player + 1:
                        winning_count += 1
                        break  # Only need one color to satisfy the condition

        return winning_count

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Calculate flips needed for all rows to be palindromic
        row_flips = 0
        for i in range(m):
            for j in range(n // 2):
                # Compare position j with position n-1-j
                if grid[i][j] != grid[i][n - 1 - j]:
                    row_flips += 1

        # Calculate flips needed for all columns to be palindromic
        col_flips = 0
        for j in range(n):
            for i in range(m // 2):
                # Compare position i with position m-1-i
                if grid[i][j] != grid[m - 1 - i][j]:
                    col_flips += 1

        # Return the minimum of the two options
        return min(row_flips, col_flips)

from collections import defaultdict, deque
from typing import List

class Solution:
    def timeTaken(self, edges: List[List[int]]) -> List[int]:
        n = len(edges) + 1

        # Build adjacency list
        graph = defaultdict(list)
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)

        def get_time(start):
            times = [-1] * n
            times[start] = 0

            # BFS to propagate markings
            queue = deque([start])

            while queue:
                node = queue.popleft()

                for neighbor in graph[node]:
                    if times[neighbor] == -1:
                        if node % 2 == 1:  # odd node
                            times[neighbor] = times[node] + 1
                        else:  # even node
                            times[neighbor] = times[node] + 2
                        queue.append(neighbor)

            return max(times)

        return [get_time(i) for i in range(n)]

