N = int(input())

# Read the 3D array
A = [[[0 for _ in range(N+1)] for _ in range(N+1)] for _ in range(N+1)]

for x in range(1, N+1):
    for y in range(1, N+1):
        row = list(map(int, input().split()))
        for z in range(1, N+1):
            A[x][y][z] = row[z-1]

# Build 3D prefix sum array
prefix = [[[0 for _ in range(N+1)] for _ in range(N+1)] for _ in range(N+1)]

for x in range(1, N+1):
    for y in range(1, N+1):
        for z in range(1, N+1):
            # Sum of elements from (1,1,1) to (x,y,z)
            prefix[x][y][z] = A[x][y][z]
            if x > 1:
                prefix[x][y][z] += prefix[x-1][y][z]
            if y > 1:
                prefix[x][y][z] += prefix[x][y-1][z]
            if z > 1:
                prefix[x][y][z] += prefix[x][y][z-1]
            # Subtract overlaps
            if x > 1 and y > 1:
                prefix[x][y][z] -= prefix[x-1][y-1][z]
            if x > 1 and z > 1:
                prefix[x][y][z] -= prefix[x-1][y][z-1]
            if y > 1 and z > 1:
                prefix[x][y][z] -= prefix[x][y-1][z-1]
            # Add back triple overlap
            if x > 1 and y > 1 and z > 1:
                prefix[x][y][z] += prefix[x-1][y-1][z-1]

# Process queries
Q = int(input())
for _ in range(Q):
    Lx, Rx, Ly, Ry, Lz, Rz = map(int, input().split())

    # Using inclusion-exclusion to get sum from (Lx,Ly,Lz) to (Rx,Ry,Rz)
    result = 0

    # Sum from (1,1,1) to (Rx,Ry,Rz)
    result += prefix[Rx][Ry][Rz]

    # Subtract sums from (1,1,1) to (Lx-1,Ry,Rz), (Rx,Ly-1,Rz), (Rx,Ry,Lz-1)
    if Lx > 1:
        result -= prefix[Lx-1][Ry][Rz]
    if Ly > 1:
        result -= prefix[Rx][Ly-1][Rz]
    if Lz > 1:
        result -= prefix[Rx][Ry][Lz-1]

    # Add back the parts that were subtracted twice
    if Lx > 1 and Ly > 1:
        result += prefix[Lx-1][Ly-1][Rz]
    if Lx > 1 and Lz > 1:
        result += prefix[Lx-1][Ry][Lz-1]
    if Ly > 1 and Lz > 1:
        result += prefix[Rx][Ly-1][Lz-1]

    # Subtract the part that was added back too many times
    if Lx > 1 and Ly > 1 and Lz > 1:
        result -= prefix[Lx-1][Ly-1][Lz-1]

    print(result)
